 24	/// 2026-11-09, FR-MCP-BUILD-001; TR-MCP-NUKE-019 AC-7; R15-F1: replaces the stale recorded-count binding with
 25	/// case identities discovered from each selected project at target run time.
 26	/// </remarks>
 27	internal static class TestProjectCaseDiscovery
 28	{
 29	    /// <summary>Discovers and classifies one project's cases for the ownership decision.</summary>
 30	    /// <param name="projectName">The declared project name.</param>
 31	    /// <param name="projectPath">The test project file.</param>
 32	    /// <param name="role">The role declared by <see cref="TestProjectRoles"/>.</param>
 33	    /// <param name="source">The runtime discovery boundary.</param>
 34	    /// <returns>The project role and every discovered case identity, kind and quarantine state.</returns>
 35	    /// <exception cref="InvalidOperationException">A discovery result is empty, duplicated or not a subset of all cases.</exception>
 36	    internal static TestProjectInventory Discover(
 37	        string projectName,
 38	        string projectPath,
 39	        TestProjectRole role,
 40	        ITestCaseDiscoverySource source)
 41	    {
 42	        ArgumentException.ThrowIfNullOrWhiteSpace(projectName);
 43	        ArgumentException.ThrowIfNullOrWhiteSpace(projectPath);
 44	        ArgumentNullException.ThrowIfNull(source);
 45	
 46	        var all = Unique(projectName, "all", source.Discover(projectPath, null));
 47	        if (all.Count == 0)
 48	            throw new InvalidOperationException($"Runtime discovery found no test case in '{projectName}'.");
 49	
 50	        var integration = Unique(projectName, "Category=Integration", source.Discover(projectPath, "Category=Integration"));
 51	        var quarantined = Unique(projectName, TestQuarantine.Trait + "=" + TestQuarantine.NoMatchingCriterion,
 52	            source.Discover(projectPath, TestQuarantine.Trait + "=" + TestQuarantine.NoMatchingCriterion));
 53	        RequireSubset(projectName, integration, all, "integration");
 54	        RequireSubset(projectName, quarantined, all, "quarantined");
 55	
 56	        var integrationSet = integration.ToHashSet(StringComparer.Ordinal);
 57	        var quarantineSet = quarantined.ToHashSet(StringComparer.Ordinal);
 58	        var cases = all.Select(name => new TestCaseEntry(
 59	            name,
 60	            integrationSet.Contains(name) ? TestCaseKind.Integration : NonIntegrationKind(role),
 61	            quarantineSet.Contains(name))).ToArray();
 62	        return new TestProjectInventory(projectName, role, cases);
 63	    }
 64	
 65	    /// <summary>Returns the non-integration kind that exposes a missing Integration trait as a foreign case.</summary>
 66	    /// <param name="role">The declared project role.</param>
 67	    /// <returns>Infrastructure for infrastructure projects; unit otherwise.</returns>
 68	    private static TestCaseKind NonIntegrationKind(TestProjectRole role)
 69	        => role == TestProjectRole.Infrastructure ? TestCaseKind.Infrastructure : TestCaseKind.Unit;
 70	
 71	    /// <summary>Rejects duplicate discovered identities without changing runner order.</summary>
 72	    /// <param name="projectName">The project being discovered.</param>
 73	    /// <param name="selection">The discovery filter label.</param>
 74	    /// <param name="cases">The runner result.</param>
 75	    /// <returns>The copied identities.</returns>
 76	    private static IReadOnlyList<string> Unique(string projectName, string selection, IReadOnlyList<string> cases)
 77	    {
 78	        ArgumentNullException.ThrowIfNull(cases);
 79	        var duplicates = cases.GroupBy(name => name, StringComparer.Ordinal).Where(group => group.Count() > 1)
 80	            .Select(group => group.Key).ToArray();
 81	        if (duplicates.Length > 0)
 82	            throw new InvalidOperationException($"Runtime discovery for '{projectName}' ({selection}) repeated: {string.Join(", ", duplicates)}.");
 83	        return cases.ToArray();
 84	    }
 85	
 86	    /// <summary>Rejects filtered identities that the same project's unfiltered discovery did not return.</summary>
 87	    /// <param name="projectName">The project being discovered.</param>
 88	    /// <param name="filtered">The filtered discovery result.</param>
 89	    /// <param name="all">The unfiltered discovery result.</param>
 90	    /// <param name="selection">The filtered result label.</param>
 91	    private static void RequireSubset(string projectName, IReadOnlyList<string> filtered, IReadOnlyList<string> all, string selection)
 92	    {
 93	        var unknown = filtered.Except(all, StringComparer.Ordinal).ToArray();
 94	        if (unknown.Length > 0)
 95	            throw new InvalidOperationException($"Runtime {selection} discovery for '{projectName}' returned identities absent from all-case discovery: {string.Join(", ", unknown)}.");
 96	    }
 97	}
