  2	
  3	/// <summary>
  4	/// TR-MCP-NUKE-019 AC-7 scripted discovery contract: proves ownership inventories come from discovered identities and
  5	/// that role/category drift fails the owning target instead of disappearing behind a test filter.
  6	/// </summary>
  7	/// <remarks>
  8	/// 2026-11-09, FR-MCP-BUILD-001; TR-MCP-NUKE-019 AC-7; R15-F1: added before binding the runtime list-tests source to
  9	/// Test and MigrationIntegrationTests. The scripted source is hermetic and each negative control changes one discovery
 10	/// result while keeping the declared role fixed.
 11	/// </remarks>
 12	public sealed class TestProjectCaseDiscoveryTests
 13	{
 14	    /// <summary>Proves the inventory identities and kinds come from the discovery source, with no recorded-count input.</summary>
 15	    /// <remarks>2026-11-09, FR-MCP-BUILD-001; TR-MCP-NUKE-019 AC-7; R15-F1: required discovery-source positive control.</remarks>
 16	    [Fact]
 17	    public void OwnershipInventory_ComesFromDiscoveredCases_NotRecordedCounts()
 18	    {
 19	        var source = new ScriptedDiscoverySource(
 20	            all: ["UnitCase", "IntegrationCase", "QuarantinedCase"],
 21	            integration: ["IntegrationCase"],
 22	            quarantined: ["QuarantinedCase"]);
 23	
 24	        var inventory = TestProjectCaseDiscovery.Discover("Project.Tests", "Project.Tests.csproj", TestProjectRole.Unit, source);
 25	
 26	        Assert.Equal([null, "Category=Integration", "Quarantine=NoMatchingCriterion"], source.Filters);
 27	        Assert.Collection(
 28	            inventory.Cases,
 29	            item => Assert.Equal(new TestCaseEntry("UnitCase", TestCaseKind.Unit), item),
 30	            item => Assert.Equal(new TestCaseEntry("IntegrationCase", TestCaseKind.Integration), item),
 31	            item => Assert.Equal(new TestCaseEntry("QuarantinedCase", TestCaseKind.Unit, Quarantined: true), item));
 32	    }
 33	
 34	    /// <summary>Proves Test fails when runtime discovery finds an integration case in a unit-owned project.</summary>
 35	    /// <remarks>2026-11-09, FR-MCP-BUILD-001; TR-MCP-NUKE-019 AC-7; R15-F1: required unit-target negative control.</remarks>
 36	    [Fact]
 37	    public void UnitOwnedProject_WithDiscoveredIntegrationCase_FailsTestTarget()
 38	    {
 39	        var inventory = TestProjectCaseDiscovery.Discover(
 40	            "Project.Tests",
 41	            "Project.Tests.csproj",
 42	            TestProjectRole.Unit,
 43	            new ScriptedDiscoverySource(["UnitCase", "IntegrationCase"], ["IntegrationCase"], []));
 44	        var outcome = new TestProjectOwnership().Decide(TestSelectionKind.Unit, [inventory]);
 45	
 46	        var failure = Assert.Throws<InvalidOperationException>(() => TestProjectOwnershipGate.RequireAccepted("Test", outcome));
 47	
 48	        Assert.Contains("Project.Tests (RejectedForeignCase)", failure.Message, StringComparison.Ordinal);
 49	    }
 50	
 51	    /// <summary>Proves the integration lane fails when runtime discovery finds a case without Category=Integration.</summary>
 52	    /// <remarks>2026-11-09, FR-MCP-BUILD-001; TR-MCP-NUKE-019 AC-7; R15-F1: required lane negative control.</remarks>
 53	    [Fact]
 54	    public void IntegrationOwnedProject_WithDiscoveredUnitCase_FailsLane()
 55	    {
 56	        var inventory = TestProjectCaseDiscovery.Discover(
 57	            "Project.IntegrationTests",
 58	            "Project.IntegrationTests.csproj",
 59	            TestProjectRole.Integration,
 60	            new ScriptedDiscoverySource(["IntegrationCase", "MissingTraitCase"], ["IntegrationCase"], []));
 61	        var outcome = new TestProjectOwnership().Decide(TestSelectionKind.Integration, [inventory]);
 62	
 63	        var failure = Assert.Throws<InvalidOperationException>(() => TestProjectOwnershipGate.RequireAccepted("MigrationIntegrationTests", outcome));
 64	
 65	        Assert.Contains("Project.IntegrationTests (RejectedForeignCase)", failure.Message, StringComparison.Ordinal);
 66	    }
 67	
 68	    /// <summary>Proves one newly discovered foreign case invalidates a previously clean recorded count.</summary>
 69	    /// <remarks>2026-11-09, FR-MCP-BUILD-001; TR-MCP-NUKE-019 AC-7; R15-F1: required stale-count drift negative control.</remarks>
 70	    [Fact]
 71	    public void RecordedCountDrift_IsRejected()
 72	    {
 73	        const int historicalRecordedUnitCount = 1;
 74	        var source = new ScriptedDiscoverySource(
 75	            ["HistoricalUnitCase", "NewIntegrationCase"],
 76	            ["NewIntegrationCase"],
 77	            []);
 78	        var inventory = TestProjectCaseDiscovery.Discover("Project.Tests", "Project.Tests.csproj", TestProjectRole.Unit, source);
 79	        var outcome = new TestProjectOwnership().Decide(TestSelectionKind.Unit, [inventory]);
 80	
 81	        Assert.Equal(historicalRecordedUnitCount + 1, inventory.Cases.Count);
 82	        Assert.Throws<InvalidOperationException>(() => TestProjectOwnershipGate.RequireAccepted("Test", outcome));
 83	    }
 84	
 85	    /// <summary>Proves the runtime-output parser preserves indented identities and treats an empty filtered list as empty.</summary>
 86	    /// <remarks>2026-11-09, FR-MCP-BUILD-001; TR-MCP-NUKE-019 AC-7; R15-F1: binds the scripted contract to VSTest output shape.</remarks>
 87	    [Fact]
 88	    public void DotNetListTestDiscovery_ParsesCasesAndEmptyFilterResult()
 89	    {
 90	        var cases = DotNetListTestDiscoverySource.Parse(
 91	            ["build output", "The following Tests are available:", "    Namespace.Class.Case", "    Namespace.Class.Theory(value: 1)"]);
 92	        var empty = DotNetListTestDiscoverySource.Parse(
 93	            ["The following Tests are available:", "No test matches the given testcase filter `Category=Integration` in Project.Tests.dll"]);
 94	
 95	        Assert.Equal(["Namespace.Class.Case", "Namespace.Class.Theory(value: 1)"], cases);
 96	        Assert.Empty(empty);
 97	    }
 98	
 99	    /// <summary>Proves an empty unfiltered discovery fails before a target can report success.</summary>
100	    /// <remarks>2026-11-09, FR-MCP-BUILD-001; TR-MCP-NUKE-019 AC-7; R16-F2: required empty-result negative control.</remarks>
150	        var cases = DotNetListTestDiscoverySource.Parse(
151	            ["The following Tests are available:", "    Namespace.Class.First", "Build succeeded.", "    Namespace.Class.AfterBoundary"]);
152	
153	        Assert.Equal(["Namespace.Class.First"], cases);
154	    }
155	
156	    /// <summary>Hermetic discovery source keyed by the exact filters the production composer requests.</summary>
157	    /// <remarks>2026-11-09, FR-MCP-BUILD-001; TR-MCP-NUKE-019 AC-7; R15-F1: added with the scripted discovery contract.</remarks>
158	    private sealed class ScriptedDiscoverySource(
159	        IReadOnlyList<string> all,
160	        IReadOnlyList<string> integration,
161	        IReadOnlyList<string> quarantined) : ITestCaseDiscoverySource
162	    {
163	        private readonly List<string?> filters = [];
164	
165	        /// <summary>Gets the requested filters in call order.</summary>
166	        internal IReadOnlyList<string?> Filters => filters;
167	
168	        /// <inheritdoc />
169	        public IReadOnlyList<string> Discover(string projectPath, string? filter)
170	        {
171	            filters.Add(filter);
172	            return filter switch
173	            {
174	                null => all,
175	                "Category=Integration" => integration,
176	                "Quarantine=NoMatchingCriterion" => quarantined,
177	                _ => throw new InvalidOperationException($"Unexpected scripted filter '{filter}'."),
178	            };
179	        }
180	    }
181	}

